122	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
123	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
124	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
125	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
126	    }
127	
128	    // FPR restore (requires mstatus.FS enabled above): one abstract register
129	    // write per f-reg. Abstract-only by design, like every non-V register
130	    // block -- the Program Buffer is reserved for state the abstract command
131	    // space cannot reach (the V regfile, vtype/vl).
132	    if (state.flags & HYBRID_FLAG_FP) {
133	      for (uint16_t i = 0; i < 32; ++i)
134	        write_64bit_register(regno_fpr(i), state.fpr[i]);
135	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
136	      // fallback scratch x5 is overwritten by the GPR loop below.
137	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
138	    }
139	
140	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
141	    // the GPR loop overwrites x5 afterward so state is preserved).
142	    if (state.flags & HYBRID_FLAG_V) {
143	      // V data regfile: reload v0..v31 from the shared scratch region via the
144	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
145	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
146	      // the restore then overwrites with the architectural values. The sweep
147	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
148	      // below restores all three. The scratch is vlenb-packed
149	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
150	      if (scratch_gpa_ == kVScratchGpaUnset)
151	        throw std::runtime_error(
152	          "ResumeDriver::resume: V state present but scratch GPA unset");
153	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
154	
155	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
156	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
157	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
158	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
159	      write_64bit_register(regno_gpr(5), state.vl);
160	      write_64bit_register(regno_gpr(6), state.vtype);
161	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
162	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
163	
164	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
165	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
166	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
167	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
168	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
169	    }
170	
171	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
172	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
173	    // in the drained privilege; M-mode states skip the write (prv already 3).
174	    // Before the GPR loop: a PB fallback would clobber scratch x5.
175	    if (state.priv != 3) {
176	      // L2 slice: with PMP implemented and no matching entry, every S/U
177	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
178	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
179	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
180	      // RV64. Tolerant writes: entries beyond what the hart implements
181	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
182	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
183	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
184	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
185	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
186	
187	      const uint64_t dcsr =
188	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
189	      write_csr_abstract_or_pb(kCsrDcsr,
190	                               (dcsr & ~uint64_t{0x3}) | state.priv);
191	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
192	      // silently measure the ROI in the wrong privilege. Verify and abort.
193	      const uint64_t got =
194	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
195	        & 0x3u;
196	      if (got != state.priv)
197	        throw std::runtime_error(
198	          "ResumeDriver::resume: engine does not implement privilege level "
199	          + std::to_string(state.priv)
200	          + " (dcsr.prv pinned to " + std::to_string(got)
201	          + "); pick an S/U-capable engine");
202	    }
203	
204	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite): one
205	    // abstract register write per GPR.
206	    for (uint16_t i = 1; i < 32; ++i)
207	      write_64bit_register(regno_gpr(i), state.gpr[i]);
208	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
209	
210	    write_csr_tolerant(kCsrMtvec, state.mtvec);
211	
212	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
213	    // register with no hardware side effects, legal to use inside a trap-free
214	    // ROI. Restore it so a value stashed before the handoff survives into the
215	    // vsim phase.
216	    write_csr_tolerant(kCsrMscratch, state.mscratch);
217	
218	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
219	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
220	    // value stashed before the handoff must survive into the vsim phase (same
221	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
222	    // hardware-driven pending bits, or mtval on a core that hardwires it)
223	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
224	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
225	    write_csr_tolerant(kCsrMepc,   state.mepc);
226	    write_csr_tolerant(kCsrMcause, state.mcause);
227	    write_csr_tolerant(kCsrMtval,  state.mtval);
228	    write_csr_tolerant(kCsrMie,    state.mie);
229	    write_csr_tolerant(kCsrMip,    state.mip);
230	
231	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
232	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
233	    // caches) but has no cache model, so without this the cycle engine resumes
234	    // at the ROI with caches at their reset default -- DISABLED -- and the
235	    // whole measured window runs uncached, inflating it severalfold. Tolerant
236	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
237	    // write as a no-op, and a drained 0 (caches were off) restores the reset
238	    // state, so this is always safe to issue.
239	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
240	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
241	
242	    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
243	    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
244	    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
245	    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
246	    // mcache_ctl: without them the cycle engine resumes with the wrong memory
247	    // system or faults on the first CoDense/DSP op in the window. All tolerant:
248	    // a core lacking a given custom CSR mirrors the write as a no-op, and a
249	    // drained 0 restores the reset value. HYBRID_ANDES_CSR_LIST is the single
250	    // source of truth shared with the plugin drain, StateDrain, and state_diff.
251	    if (state.flags & HYBRID_FLAG_ANDES) {
252	#define X(field, addr, name) write_csr_tolerant(addr, state.andes.field);
253	      HYBRID_ANDES_CSR_LIST(X)
254	#undef X
255	      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
256	      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
257	      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
258	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
259	        write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
260	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
261	        write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
262	    }
263	
264	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
265	    // from QEMU1's drain value. Without this, vsim's local counter starts
266	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
267	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
268	    // overwrite here as the GPR loop already ran.
269	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
270	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
271	
272	    clear_cmderr_if_set();
273	    request_resume();
274	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
275	                   "ResumeDriver resume");
276	  }
277	
278	private:
279	  void request_halt()
280	  {
281	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
282	  }
283	
284	  void request_resume()
285	  {
286	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
287	  }
288	
289	  void write_64bit_register(uint16_t regno, uint64_t value)
290	  {
291	    write_register_abstract(bus_, regno, value);
292	  }
293	
294	  // Abstract-first CSR write with Program Buffer fallback.
295	  // Tries an abstract register write; if the DM signals cmderr, clears it,
296	  // stages the value in scratch_gpr via abstract GPR write, then executes a
297	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
298	  // to x5 (t0) which the GPR restore loop overwrites later.
299	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
300	                                 uint8_t scratch_gpr = 5)
301	  {
302	    write_64bit_register(regno_csr(csr), value);
303	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
304	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
305	    write_64bit_register(regno_gpr(scratch_gpr), value);
306	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
307	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
308	  }
309	
310	  // Write a CSR-addressable register and clear any cmderr the DM raised.
311	  // Used for CSRs whose abstract-access support may be implementation
312	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
313	  // remaining writes.
314	  void write_csr_tolerant(uint16_t csr, uint64_t value)
315	  {
316	    write_64bit_register(regno_csr(csr), value);
317	    clear_cmderr_if_set();
318	  }
319	
320	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
321	  // is rejected until the bits are W1C-cleared. We tolerate per-register
322	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
323	  // error before resuming so the hart isn't left in a stuck state.
324	  // B17: record the last observed non-zero cmderr and a clear count so a
325	  // partially-broken restore is observable via the public accessors
326	  // instead of silently swallowed.
327	  void clear_cmderr_if_set()
328	  {
329	    const auto status = bus_.read(kAbstractcs);
330	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
331	    if (code != 0u) {
332	      last_observed_cmderr_ = code;
333	      ++cmderr_clear_count_;
334	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
335	    }
336	  }
337	
338	  DmiBus& bus_;
339	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
340	  uint32_t last_observed_cmderr_ = 0;
341	  uint64_t cmderr_clear_count_   = 0;
342	
343	public:
344	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
345	  // at least one abstract write tripped a sticky cmderr the restore
346	  // tolerated by clearing. cmderr_clear_count() is the total number of
347	  // such clears across all calls into clear_cmderr_if_set() this run.
348	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
349	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
350	};
351	
352	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
353	// via an Abstract Command. Halts-and-reads contract: caller must have the
354	// hart in the halted state. Shared by StateDrain (drain at exit). If
355	// abstractcs.cmderr goes sticky after the command, the helper clears it and
356	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
357	// instead of corrupting the adjacent field.
358	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
359	                                     const char* poll_label
360	                                       = "read_register_64")
361	  -> std::optional<uint64_t>
362	{
363	  using RD = ResumeDriver;
364	  bus.write(RD::kCommand,
365	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
366	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
367	  const auto status = bus.read(RD::kAbstractcs);
368	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
369	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
370	    return std::nullopt;
371	  }
372	  const uint64_t lo = bus.read(RD::kData0);
373	  const uint64_t hi = bus.read(RD::kData1);
374	  return lo | (hi << 32);
375	}
376	
377	inline auto read_register_64(DmiBus& bus, uint16_t regno,
378	                             const char* poll_label = "read_register_64")
379	  -> uint64_t
380	{
381	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
382	}
