74	
75	    if (input.flags & HYBRID_FLAG_V) {
76	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
77	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
78	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
79	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
80	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
81	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
82	    }
83	
84	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
85	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
86	    // dropped and the stale QEMU1 value passes through into the drained state.
87	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
88	
89	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
90	    // restores them), so re-read them -- an in-ROI write must reach the drained
91	    // state instead of the stale QEMU1 passthrough value.
92	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
93	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
94	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
95	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
96	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
97	
98	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
99	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
100	
101	    // Andes V5 CSR block (v3): re-read the transported Andes CSRs from the hart
102	    // so an in-ROI write reaches the drained state instead of the stale QEMU1
103	    // passthrough (same round-trip as mscratch). Tolerant reads: a CSR the core
104	    // lacks mirrors as 0. HYBRID_ANDES_CSR_LIST is the single source of truth
105	    // shared with the plugin drain, ResumeDriver, and state_diff.
106	    if (input.flags & HYBRID_FLAG_ANDES) {
107	#define X(field, addr, name) state.andes.field = read_register_64(bus_, regno_csr(addr));
108	      HYBRID_ANDES_CSR_LIST(X)
109	#undef X
110	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
111	        state.andes.pmacfg[i] =
112	          read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
113	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
114	        state.andes.pmaaddr[i] =
115	          read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
116	    }
117	
118	    // V data regfile: dump v0..v31 to the shared scratch region via the
119	    // Program Buffer LAST -- after every architectural read above -- so the
120	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
121	    // cannot corrupt the values already captured. The simulator's
122	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
123	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
124	    if (input.flags & HYBRID_FLAG_V)
125	      dump_v_to_scratch(input.vlenb);
126	
127	    return state;
128	  }
129	
130	private:
131	  // Halt the hart and capture the two control fields every drain path needs:
132	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
133	  // blocks are filled by the caller, so drain() and drain_with_passthrough
134	  // share one halt + prologue. dmactive must transition 0->1 in its own write
135	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
136	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
137	  {
138	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
139	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
140	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
141	                   "StateDrain halt");
142	
143	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
144	                                  "StateDrain DCSR") & 0x3u;
145	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
146	  }
147	
148	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
149	  // L26: guards on the configured scratch GPA so a V drain never stores to a
150	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
151	  void dump_v_to_scratch(uint64_t vlenb)
152	  {
153	    if (scratch_gpa_ == kVScratchGpaUnset)
154	      throw std::runtime_error(
155	        "StateDrain: V state present but scratch GPA unset");
156	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
157	  }
158	
159	  DmiBus& bus_;
160	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
161	};
